package dev.travellerscompanions.qa;

import dev.travellerscompanions.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.gametest.*;

@GameTestHolder(TravellersCompanions.ID)
@PrefixGameTestTemplate(false)
public final class CompanionGameTests {
    private static final Set<BlockPos> PREPARED_ARENAS=new HashSet<>();
    @GameTest(template="empty") public static void oldFourCharacterRosterGainsMaraWithoutChangingExistingEntries(GameTestHelper t){
        var old=new CompoundTag();old.putInt("Active",3);var lease=UUID.randomUUID();old.putUUID("Entity",lease);var entries=new ListTag();
        for(int i=0;i<4;i++){var entry=new CompanionData.Entry();entry.level=i+2;entry.bond=20+i;entry.readyAt=123456789L+i;entry.initialized=true;entry.snapshot.putString("Marker","old-"+i);entries.add(entry.save());}old.put("Entries",entries);
        var loaded=CompanionData.Roster.load(old);
        t.assertTrue(loaded.entries.length==CharacterKind.COUNT&&loaded.party.size()==1&&lease.equals(loaded.party.get(3)),"Legacy roster/lease changed");
        for(int i=0;i<4;i++)t.assertTrue(loaded.entries[i].level==i+2&&loaded.entries[i].bond==20+i&&loaded.entries[i].readyAt==123456789L+i&&loaded.entries[i].snapshot.getString("Marker").equals("old-"+i),"Old companion state changed");
        var mara=loaded.entries[4];t.assertTrue(mara.level==1&&!mara.initialized&&mara.readyAt==0&&mara.snapshot.isEmpty(),"Mara did not start fresh");t.succeed();
    }
    @GameTest(template="empty") public static void maraTrainsSynchronizesAndSurvivesSaveAndResummon(GameTestHelper t){
        var p=player(t);var e=summon(t,p,CharacterKind.MARA.ordinal());
        t.assertTrue(e.kind()==CharacterKind.MARA&&e.getMainHandItem().is(Items.CROSSBOW)&&e.backpack.countItem(Items.ARROW)==64,"Mara starter missing");
        p.getInventory().add(new ItemStack(Items.EMERALD,4));t.assertTrue(CompanionService.train(p,4).isEmpty()&&e.companionLevel()==2&&p.getInventory().countItem(Items.EMERALD)==0,"Mara training failed");
        e.backpack.getItem(0).shrink(7);e.getMainHandItem().setDamageValue(7);e.checkpoint();var tag=new CompoundTag();e.saveWithoutId(tag);
        var clone=TravellersCompanions.COMPANION.get().create(t.getLevel());clone.load(tag);t.assertTrue(clone.kind()==CharacterKind.MARA&&clone.companionLevel()==2&&clone.backpack.countItem(Items.ARROW)==57,"Mara entity save lost identity or inventory");
        var state=CompanionNetwork.state(p);t.assertTrue(state.getInt("Active")==4&&state.getList("Companions",Tag.TAG_COMPOUND).size()==CharacterKind.COUNT&&state.getList("Companions",Tag.TAG_COMPOUND).getCompound(4).getInt("Level")==2,"Mara absent from network state");
        var saved=CompanionData.Roster.load(CompanionData.get(p.server).roster(p.getUUID()).save());t.assertTrue(saved.party.containsKey(4)&&saved.entries[4].level==2,"Mara roster save failed");
        CompanionService.dismiss(p);e=summon(t,p,4);t.assertTrue(e.backpack.countItem(Items.ARROW)==57&&e.getMainHandItem().getDamageValue()==7,"Mara starter duplicated or gear reset");
        for(int level:new int[]{1,3,8,15})for(int variant=0;variant<4;variant++)t.assertFalse(e.kind().dialogue(level,variant).isEmpty(),"Mara dialogue missing");t.succeed();
    }
    @GameTest(template="empty",timeoutTicks=220) public static void maraChargesCrossbowAndConsumesAmmoWhenHittingMonster(GameTestHelper t){
        var p=player(t);var e=summon(t,p,4);e.setHolding(true);var mob=t.spawn(EntityType.HUSK,10,2,7);mob.moveTo(e.position().add(5,0,0));p.moveTo(e.position().add(-3,0,0));mob.setNoAi(true);mob.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);mob.setHealth(100);e.setTarget(mob);
        t.runAfterDelay(12,()->t.assertTrue(e.backpack.countItem(Items.ARROW)==64,"Crossbow fired before charging"));
        t.succeedWhen(()->{t.assertTrue(e.backpack.countItem(Items.ARROW)<64&&mob.getHealth()<100&&e.getMainHandItem().getDamageValue()>0,"Mara: ammo="+e.backpack.countItem(Items.ARROW)+" / hp="+mob.getHealth()+" / wear="+e.getMainHandItem().getDamageValue()+" / target="+e.getTarget()+" / pos="+e.position()+" / victim="+mob.position()+" / removed="+e.isRemoved());
            t.assertTrue(t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.projectile.AbstractArrow.class,e.getBoundingBox().inflate(20),a->a.getOwner()==e&&a.shotFromCrossbow()).size()>0,"Projectile not marked as crossbow shot");});
    }
    @GameTest(template="empty") public static void monsterPolicyProtectsNeutralMobsAndRecognizesOtherMonsterClasses(GameTestHelper t){
        var p=player(t);var e=summon(t,p,4);
        for(var type:new EntityType<?>[]{EntityType.COW,EntityType.VILLAGER,EntityType.WOLF,EntityType.BEE,EntityType.IRON_GOLEM,EntityType.ENDERMAN,EntityType.ZOMBIFIED_PIGLIN,EntityType.PIGLIN}){
            var mob=(LivingEntity)type.create(t.getLevel());t.assertFalse(e.canAttack(mob),"Companion can attack "+type);e.setTarget(mob);t.assertTrue(e.getTarget()==null,"Target setter accepted "+type);
            var arrow=new net.minecraft.world.entity.projectile.Arrow(t.getLevel(),e);var event=new net.minecraftforge.event.entity.living.LivingAttackEvent(mob,t.getLevel().damageSources().arrow(arrow,e),8);net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(event);t.assertTrue(event.isCanceled(),"Stray arrow could damage "+type);
        }
        for(var type:new EntityType<?>[]{EntityType.HUSK,EntityType.CREEPER,EntityType.SLIME,EntityType.GHAST,EntityType.PHANTOM,EntityType.PIGLIN_BRUTE}){
            var mob=(LivingEntity)type.create(t.getLevel());t.assertTrue(e.canAttack(mob),"Monster wrongly excluded: "+type);
            var event=new net.minecraftforge.event.entity.living.LivingAttackEvent(mob,t.getLevel().damageSources().mobAttack(e),8);net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(event);t.assertFalse(event.isCanceled(),"Monster damage canceled: "+type);
        }t.succeed();
    }
    static ServerPlayer player(GameTestHelper t){
        // Forge reuses the GameTest world. Old mobs can otherwise overlap new targets and absorb projectiles.
        var origin=t.absolutePos(BlockPos.ZERO);
        if(PREPARED_ARENAS.add(origin))for(var entity:t.getLevel().getEntitiesOfClass(Entity.class,new net.minecraft.world.phys.AABB(origin,origin.offset(48,8,48))))entity.discard();
        var p=net.minecraftforge.common.util.FakePlayerFactory.get(t.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"CompanionQA"));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.moveTo(t.absolutePos(new BlockPos(7,2,7)),0,0);t.getLevel().addNewPlayer(p);for(int x=0;x<15;x++)for(int z=0;z<15;z++)t.setBlock(x,1,z,Blocks.STONE);return p;
    }
    static CompanionEntity summon(GameTestHelper t,ServerPlayer p,int i){String error=CompanionService.summon(p,i);t.assertTrue(error.isEmpty(),"Summon failed: "+error);return CompanionService.active(p,i);}
    @GameTest(template="empty") public static void allCharactersHaveDistinctStatsAndStarters(GameTestHelper t){var p=player(t);for(int i=0;i<CharacterKind.COUNT;i++){var e=summon(t,p,i);t.assertTrue(e.isTame()&&e.ownedBy(p),"Not auto tamed");t.assertTrue(e.getMaxHealth()==CharacterKind.of(i).health,"Wrong health");t.assertFalse(e.getMainHandItem().isEmpty(),"Starter missing");if(i==0)t.assertTrue(e.getMainHandItem().is(Items.BOW)&&e.backpack.countItem(Items.ARROW)==64,"Archer loadout");if(i==2)t.assertTrue(e.getOffhandItem().is(Items.SHIELD),"Shield missing");if(i==3&&net.minecraftforge.fml.ModList.get().isLoaded("magistuarmory"))t.assertTrue(net.minecraftforge.registries.ForgeRegistries.ITEMS.getKey(e.getMainHandItem().getItem()).toString().equals(TravellersCompanions.SPEAR.get()),"Epic Knights spear did not resolve");CompanionService.dismiss(p);}t.succeed();}

    @GameTest(template="empty") public static void dismissPreservesBackpackAndGearWithoutStarterDuplication(GameTestHelper t){var p=player(t);var e=summon(t,p,0);e.backpack.clearContent();e.backpack.setItem(0,new ItemStack(Items.DIAMOND,17));e.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.DIAMOND_AXE));e.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));CompanionService.dismiss(p);var again=summon(t,p,0);t.assertTrue(again.backpack.countItem(Items.DIAMOND)==17&&again.backpack.countItem(Items.ARROW)==0,"Items changed or starter arrows regenerated");t.assertTrue(again.getMainHandItem().is(Items.DIAMOND_AXE)&&again.getItemBySlot(EquipmentSlot.HEAD).is(Items.IRON_HELMET),"Gear lost");t.succeed();}
    @GameTest(template="empty") public static void lethalDamageDismissesAndEnforcesTenMinutes(GameTestHelper t){var p=player(t);var e=summon(t,p,2);e.backpack.setItem(2,new ItemStack(Items.DIAMOND,9));long now=System.currentTimeMillis();e.hurt(t.getLevel().damageSources().generic(),10000);var r=CompanionData.get(p.server).roster(p.getUUID());t.assertTrue(e.isRemoved()&&r.party.isEmpty(),"Death not dismissed");t.assertTrue(r.entries[2].readyAt>=now+600000&&r.entries[2].readyAt<now+602000,"Not ten real minutes");t.assertFalse(CompanionService.summon(p,2).isEmpty(),"Recovery bypassed");r.entries[2].readyAt=System.currentTimeMillis()-1;var again=summon(t,p,2);t.assertTrue(again.backpack.countItem(Items.DIAMOND)==9&&again.getHealth()==again.getMaxHealth(),"Death lost inventory or health not restored");t.succeed();}
    @GameTest(template="empty") public static void emeraldTrainingIsAtomicAndCapped(GameTestHelper t){var p=player(t);var e=summon(t,p,1);t.assertFalse(CompanionService.train(p,1).isEmpty(),"Free training");p.getInventory().add(new ItemStack(Items.EMERALD,10));t.assertTrue(CompanionService.train(p,1).isEmpty(),"Paid training failed");t.assertTrue(p.getInventory().countItem(Items.EMERALD)==6&&e.companionLevel()==2&&e.getMaxHealth()==102,"Wrong price or stats");var entry=CompanionData.get(p.server).roster(p.getUUID()).entries[1];entry.level=20;t.assertFalse(CompanionService.train(p,1).isEmpty(),"Level cap bypassed");t.assertTrue(p.getInventory().countItem(Items.EMERALD)==6,"Failed purchase consumed emeralds");t.succeed();}
    @GameTest(template="empty") public static void strangersCannotCommandOrOpenInventory(GameTestHelper t){var p=player(t);var e=summon(t,p,0);var q=player(t);t.assertFalse(CompanionService.interact(q,e.getId(),6).isEmpty(),"Stranger commanded companion");t.assertFalse(e.holding(),"Stranger changed order");var menu=new CompanionMenu(0,p.getInventory(),e);t.assertFalse(menu.stillValid(q),"Stranger accessed inventory");p.setPos(p.getX()+100,p.getY(),p.getZ());t.assertFalse(CompanionService.interact(p,e.getId(),6).isEmpty(),"Remote wheel exploit");t.succeed();}
    @GameTest(template="empty") public static void dialogueUnlocksAndRallyCooldownAreAuthoritative(GameTestHelper t){var p=player(t);var e=summon(t,p,2);t.assertFalse(CompanionService.interact(p,e.getId(),8).isEmpty(),"Level 1 used Rally");var entry=CompanionData.get(p.server).roster(p.getUUID()).entries[2];entry.level=5;e.setLevel(5);t.assertTrue(CompanionService.interact(p,e.getId(),8).isEmpty(),"Rally did not unlock");t.assertTrue(p.hasEffect(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE),"Rally buff missing");t.assertFalse(CompanionService.interact(p,e.getId(),8).isEmpty(),"Rally cooldown bypassed");t.succeed();}
    @GameTest(template="empty") public static void worldLedgerRoundTripPreservesRecoveryAndEquipment(GameTestHelper t){var p=player(t);var e=summon(t,p,3);e.backpack.setItem(3,new ItemStack(Items.GOLD_INGOT,23));e.checkpoint();var data=CompanionData.get(p.server);var r=data.roster(p.getUUID());r.entries[3].readyAt=123456789L;r.entries[3].level=9;var loaded=CompanionData.load(data.save(new CompoundTag())).roster(p.getUUID());t.assertTrue(e.getUUID().equals(loaded.party.get(3))&&loaded.entries[3].readyAt==123456789L&&loaded.entries[3].level==9,"Ledger roundtrip lost state");var clone=TravellersCompanions.COMPANION.get().create(t.getLevel());clone.configure(p,3,9);clone.restore(loaded.entries[3].snapshot);t.assertTrue(clone.backpack.countItem(Items.GOLD_INGOT)==23,"Snapshot cargo missing");t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void staleEntityLeaseCannotDuplicateACompanion(GameTestHelper t){var p=player(t);var e=summon(t,p,1);var n=new CompoundTag();e.saveWithoutId(n);CompanionService.dismiss(p);var current=summon(t,p,1);var stale=TravellersCompanions.COMPANION.get().create(t.getLevel());stale.load(n);t.getLevel().addFreshEntity(stale);t.runAfterDelay(4,()->{t.assertTrue(stale.isRemoved()&&!current.isRemoved(),"Stale chunk copy survived");t.succeed();});}
    @GameTest(template="empty") public static void equipmentShiftClickConservesItems(GameTestHelper t){var p=player(t);var e=summon(t,p,1);p.getInventory().clearContent();p.getInventory().setItem(9,new ItemStack(Items.DIAMOND,12));var menu=new CompanionMenu(1,p.getInventory(),e);menu.quickMoveStack(p,33);t.assertTrue(e.backpack.countItem(Items.DIAMOND)==12&&p.getInventory().countItem(Items.DIAMOND)==0,"Deposit lost/duplicated items");menu.quickMoveStack(p,6);t.assertTrue(e.backpack.countItem(Items.DIAMOND)==0&&p.getInventory().countItem(Items.DIAMOND)==12,"Withdrawal lost/duplicated items");t.succeed();}
    @GameTest(template="empty") public static void betterCombatWeaponAttributesResolve(GameTestHelper t){var p=player(t);var e=summon(t,p,1);var attr=net.bettercombat.logic.WeaponRegistry.getAttributes(e.getMainHandItem());t.assertTrue(attr!=null&&attr.attacks().length>0,"BC attributes missing");var strike=CombatBridge.strike(e,0);t.assertTrue(strike.animation().startsWith("bettercombat:")&&strike.windup()>0&&strike.range()>2,"BC attack data not used");t.succeed();}
    @GameTest(template="empty",timeoutTicks=180) public static void meleeCompanionAcquiresAndDamagesHostiles(GameTestHelper t){var p=player(t);var e=summon(t,p,1);e.backpack.clearContent();var mob=t.spawn(EntityType.HUSK,9,2,7);mob.setNoAi(true);mob.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);mob.setHealth(100);t.succeedWhen(()->{t.assertTrue(mob.getHealth()<100,"Companion has not fought hostile");});}
    @GameTest(template="empty",timeoutTicks=150) public static void passiveCompanionDoesNotAttack(GameTestHelper t){var p=player(t);var e=summon(t,p,1);e.setStance(2);var mob=t.spawn(EntityType.HUSK,9,2,7);mob.setNoAi(true);t.runAfterDelay(70,()->{t.assertTrue(e.getTarget()==null&&mob.getHealth()==mob.getMaxHealth(),"Passive companion attacked");t.succeed();});}
    @GameTest(template="empty",timeoutTicks=200) public static void archerConsumesRealAmmunition(GameTestHelper t){var p=player(t);var e=summon(t,p,0);var mob=t.spawn(EntityType.HUSK,10,2,7);mob.setNoAi(true);mob.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);mob.setHealth(100);t.succeedWhen(()->{t.assertTrue(e.backpack.countItem(Items.ARROW)<64&&mob.getHealth()<100,"Archer did not fire and hit");});}
    @GameTest(template="empty") public static void unsafeSummonDoesNotClaimRoster(GameTestHelper t){var p=player(t);p.setPos(p.getX(),200,p.getZ());t.assertFalse(CompanionService.summon(p,0).isEmpty(),"Unsafe summon succeeded");t.assertTrue(CompanionData.get(p.server).roster(p.getUUID()).party.isEmpty(),"Failed summon claimed slot");t.succeed();}
    @GameTest(template="empty") public static void companionArrowsCannotHurtOwners(GameTestHelper t){var p=player(t);var e=summon(t,p,0);var arrow=new net.minecraft.world.entity.projectile.Arrow(t.getLevel(),e);var source=t.getLevel().damageSources().arrow(arrow,e);var event=new net.minecraftforge.event.entity.living.LivingAttackEvent(p,source,8);net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(event);t.assertTrue(event.isCanceled(),"Owner damage event was not canceled");var wolf=t.spawn(EntityType.WOLF,9,2,9);wolf.tame(p);float before=wolf.getHealth();wolf.hurt(source,8);t.assertTrue(wolf.getHealth()==before,"Friendly arrow damaged tamed pet");t.succeed();}
    @GameTest(template="empty",timeoutTicks=80) public static void defensiveCompanionRespondsToOwnerBeingHurt(GameTestHelper t){var p=player(t);var e=summon(t,p,2);e.setStance(1);var mob=t.spawn(EntityType.HUSK,10,2,7);mob.setNoAi(true);t.assertTrue(e.getTarget()==null,"Defensive companion started aggressive");/* Forge FakePlayer is permanently invulnerable; supply vanilla's remembered-attacker signal. Real damage is covered by ClientSmokeTest. */p.setLastHurtByMob(mob);t.succeedWhen(()->t.assertTrue(e.getTarget()==mob,"Companion did not defend owner"));}
    @GameTest(template="empty",timeoutTicks=150) public static void followsOwnerAndHoldStopsNavigation(GameTestHelper t){var p=player(t);var e=summon(t,p,1);e.setStance(2);p.moveTo(t.absolutePos(new BlockPos(13,2,13)),0,0);t.succeedWhen(()->{t.assertTrue(e.distanceTo(p)<4,"Companion did not follow");e.setHolding(true);t.assertTrue(e.getNavigation().isDone(),"Hold did not stop navigation");});}
}
